arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>" -H "Content-Type: application/json" -d '{"types":"public_channel,archive"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR',d); sys.exit(0)
for c in d['channels']:
    if 'incident' in c['name'].lower():
        print(c['id'], c['name'])
"

